  "plans.eyebrow": "Àwọn ètò àti àwọn ẹ̀yà",
  "plans.title": "Ṣe àfiwéra àwọn ètò StockHaven",
  "plans.intro": "Àkọọ́lẹ̀ kan, ètò èyíkéyìí tí o bá yàn — Business bo iṣòwò márùn-ún. Àwọn owó jẹ́ ti oṣooṣù ní dọ́là Amẹ́ríkà, àwọn oníbàárà ìkànnì tuntun tí ó yẹ sì lè gba ìdánwò ọjọ́ méje kan ṣoṣo káàkiri Essentials àti Business. Gbígbé ìforúkọsílẹ̀ Essentials tí ó wà tẹ́lẹ̀ sókè sí Business kò tún ìdánwò náà bẹ̀rẹ̀, bẹ́ẹ̀ ni kò ṣẹ̀dá ìdánwò ọ̀fẹ́ mìíràn. Àwọn owó ètò ìkànnì wà ṣáájú owó orí tí ó kan, bí ó bá wà. A ó fi ìgbowó rẹ gan-an hàn ọ́ kí o tó fún ìforúkọsílẹ̀ ní àṣẹ.",
