  "plans.perMonthShort": "/oṣù",
  "plans.included": "Ó wà nínú",
  "plans.notIncluded": "Kò wà nínú",
  "plans.mobileIncludedNote": "Àwọn ètò ìkànnì méjèèjì ní alábàákẹ́gbẹ́ alágbèéká nínú, nítorí náà ẹni tí ó forúkọsílẹ̀ sí ìkànnì kò ní san owó alágbèéká oṣooṣù pẹ̀lú láé.",
  "plans.priceNote": "Essentials jẹ́ $14.99/oṣù pẹ̀lú owó orí tí ó kan, bí ó bá wà. Business jẹ́ $29.99/oṣù pẹ̀lú owó orí tí ó kan, bí ó bá wà. A máa ń pinnu owó orí èyíkéyìí tí a nílò nígbà ìsanwó olùpèsè, ó sì gbọ́dọ̀ hàn nínú àpapọ̀ ìkẹyìn ṣáájú ìsanwó. Ojú ìwé àfiwéra yìí kì í ṣe ìdánilójú owó orí tàbí àṣẹ ìsanwó.",
  "plans.mobilePriceNote": "Ètò alágbèéká nìkan jẹ́ $4.99/oṣù ní owó ìpìlẹ̀ Amẹ́ríkà tí a pinnu. Ilé ìtajà App Store tàbí Google Play máa ń fi owó ìforúkọsílẹ̀ agbègbè gan-an àti owó orí èyíkéyìí tí ó kan hàn ṣáájú ríjà. Àwọn ìfàyèsílẹ̀ ọjà, ojúlé àti òṣìṣẹ́ rẹ̀ ni a ṣètò ní ìfilọ́lẹ̀, lọ́tọ̀ sí àwọn ìpele ìkànnì.",
  "plans.planChangeNote": "Olùpèsè ìsanwó gbọ́dọ̀ jẹ́rìí ìyípadà ètò ìkànnì kan. A ó ṣàlàyé owó tuntun, ọjọ́ ìbẹ̀rẹ̀ iṣẹ́ àti ìpín èyíkéyìí ṣáájú kí a tó fún ìyípadà náà ní àṣẹ. Gbígbé sókè kò yẹ kí ó ṣẹ̀dá ìforúkọsílẹ̀ kejì.",
  "plans.providerNote": "Àwọn owó, ìgbowó àti ìdánwò ni olùpèsè tí o forúkọsílẹ̀ nípasẹ̀ rẹ̀ ń ṣàkóso — App Store, Google Play, ìkànnì tàbí Shopify — kì í ṣe ojú ìwé yìí láé.",
