  "upgrade.intro": "Àwọn oníbàárà tuntun tí ó yẹ lè gba ìdánwò kan ṣoṣo ti ọjọ́ {days} fún àkọọ́lẹ̀ kan, kì í ṣe ìdánwò kan fún ètò kan. Yíyípadà láti Essentials sí Business kò bẹ̀rẹ̀ ìdánwò ọ̀fẹ́ mìíràn láé. O wà lórí",
