  "upgrade.dialogUpgradeDesc": "Ìdánwò àti ìforúkọsílẹ̀ rẹ dúró lórí ìforúkọsílẹ̀ kan náà — kò sí ìforúkọsílẹ̀ kejì, kò sí ìdánwò tuntun.",
