  "upgrade.upgradeNeverRestartsTrial": "Gbígbé sókè kò tún ìdánwò ọ̀fẹ́ rẹ bẹ̀rẹ̀ láé.",
  "upgrade.trialHistoryNote": "Tí o bá ń sanwó fún Essentials tí o sì lọ sí Business, ìwọ yóò pa àkọọ́lẹ̀ oníbàárà kan náà àti ìtàn ìdánwò mọ́. Business kò ní ìdánwò ọjọ́ méje àfikún nínú. Tí o bá gbé sókè nígbà tí ìdánwò àtilẹ̀wá rẹ ṣì ń lọ, ọjọ́ ìparí àtilẹ̀wá rẹ̀ kò tún ṣètò.",
  "upgrade.providerConfirmNote": "Àwọn ìyípadà ètò nílò ìmúdájú láti ọ̀dọ̀ olùpèsè ìsanwó. A gbọ́dọ̀ fi ìyàtọ̀ owó èyíkéyìí, ìpín àti ọjọ́ ìbẹ̀rẹ̀ iṣẹ́ hàn ṣáájú kí o tó fọwọ́sí ìyípadà náà. Gbígbé sókè kò gbọ́dọ̀ ṣẹ̀dá ìforúkọsílẹ̀ kejì ní àkókò kan náà.",
  "upgrade.chargedThroughProviderNote": "Àwọn ìyípadà ètò ni a ń gba owó rẹ̀ nípasẹ̀ olùpèsè ìsanwó. O lè fagilé ìforúkọsílẹ̀ rẹ láti ojú ìwé yìí nípa lílo bọ́tìnì Fagilé Ìforúkọsílẹ̀ lábẹ́ ètò rẹ ìsinsìnyí, tàbí láti Àwọn Ètò. Ìfagilé dá ìsọdọ̀tun ọjọ́ iwájú dúró ní òpin àkókò tí o sanwó fún; kò parí ìwọlé rẹ lẹ́sẹ̀kẹsẹ̀ láé. A kò gba owó àwọn ibi iṣẹ́ ọ̀fẹ́ tí ó wà tẹ́lẹ̀ nípa wíwo àwọn àṣàyàn wọ̀nyí.",
