  "billing.cancel.graceEndsOn": "Lẹ́yìn tí àkókò ìrọ̀rùn ọjọ́ 15 bá parí ní {date}, àkọọ́lẹ̀ rẹ àti gbogbo ìwífún rẹ̀ ni a ó pa rẹ́ pátápátá, a kò sì lè gbà á padà.",
