  "exports.eyebrow": "Dátà",
  "exports.title": "Àwọn ìjáde àti àwọn àfẹ̀yìntì",
  "exports.subtitleStart": "Àwọn ìgbàsílẹ̀ máa ń wà ní ìwọ̀n sí",
  "exports.subtitleRest": ". Gbogbo fáìlì ni a fi orúkọ ilé-iṣẹ́ àti ọjọ́ tí a ṣẹ̀dá rẹ̀ sílẹ̀.",
  "exports.createBusinessFirst": "Ṣẹ̀dá ilé-iṣẹ́ kan ní àkọ́kọ́ — àwọn ìjáde jẹ́ ti ilé-iṣẹ́, kì í ṣe ti àpù náà.",
  "exports.lockedTitle": "Àwọn ìjáde CSV àti Excel jẹ́ ẹ̀yà Business",
  "exports.lockedDesc": "Àyè iṣẹ́ rẹ wà lórí ètò Essentials. Business máa ń fi àwọn ìjáde CSV àti Excel, ìdáiyele ọjà, àwọn ọjà àti òṣìṣẹ́ tí kò ní ààlà, àwọn olùpèsè, ríra ọjà àti àwọn àdìpọ̀ kún un.",
  "exports.seeBusiness": "Wo ohun tí Business ní",
  "exports.whatTheseAre": "Ohun tí àwọn fáìlì wọ̀nyí jẹ́",
  "exports.about1": "Gbogbo ìṣètò dátà máa ń wá gẹ́gẹ́ bí CSV tàbí ìwé iṣẹ́ Excel tòótọ́ (.xlsx) — ìwé iṣẹ́ ọjà ní kíkún jẹ́ Excel nìkan, pẹ̀lú ìwé kan fún ìṣètò dátà kọ̀ọ̀kan. Àwọn fáìlì CSV máa ń ṣí ní Excel, Numbers, Google Sheets àti ọ̀pọ̀lọpọ̀ àwọn àpù ọjà. Ọ̀rọ̀ UTF-8, àwọn kọ́mà tí a fi àmì ìsọ̀rọ̀ yí ká, àwọn ìfọ́ ìlà nínú àkọsílẹ̀ àti àwọn òdo tí ó ṣáájú nínú àwọn kóòdù ni a pa mọ́ gbogbo, àti àwọn sẹ́ẹ̀lì tí ó bẹ̀rẹ̀ bí fọ́múlà ni a yí padà kí ìwé ìṣirò lè ṣí wọn gẹ́gẹ́ bí ọ̀rọ̀.",
  "exports.about2": "Nínú àwọn fáìlì Excel, àwọn SKU, UPC, ISBN àti àwọn báàkóòdù jẹ́ sẹ́ẹ̀lì ọ̀rọ̀ — kì í ṣe àmì sáyẹ́ǹsì rárá àti pé a kì í gé àwọn òdo kúrò rárá — pẹ̀lú ìbú ọ̀wọ̀n, àwọn àlẹ̀mọ́ orí àti àwọn ọ̀nà owó tàbí iye tí a lò. Ìwé iṣẹ́ ọjà ní kíkún máa ń pa àwọn ọjà, ìwọ̀n ọjà, àwọn ibùdó àti àwọn ìṣíkiri mọ́ lórí àwọn ìwé ọ̀tọ̀ọ̀tọ̀.",
  "exports.about3": "Àwọn ìjáde tí ó tóbi gan-an máa ń dúró ní ìlà 20,000 fún ìṣètò dátà kọ̀ọ̀kan — nígbà tí èyí bá ṣẹlẹ̀ orúkọ fáìlì máa ń sọ bẹ́ẹ̀ (truncated-20000), kí fáìlì díẹ̀ má baà kọjá gẹ́gẹ́ bí èyí tí ó pé.",
  "exports.about4": "Àfẹ̀yìntì jẹ́ àwòrán dátà rẹ ní àkókò kan, kì í ṣe ìmúpadà tí a fi tẹ ẹ̀ẹ̀kan. Mímú un padà jẹ́ iṣẹ́ ọwọ́, tí a ṣe àyẹ̀wò ní àkọ́kọ́, nítorí náà pa fáìlì náà mọ́ ní ààbò — kò sí ohun kan nínú àpù náà tí ó lè tún ilé-iṣẹ́ tí a pa rẹ́ ṣẹ̀dá láti inú rẹ̀ síbẹ̀. Kóòdù àpù àti àwọn àfẹ̀yìntì pẹpẹ Base44 ni a ń ṣàkóso lọ́tọ̀ sí àwọn fáìlì wọ̀nyí.",
  "exports.about5": "Àwọn fọ́tò àti àwọn àfikún ni a ṣe àkọsílẹ̀ wọn gẹ́gẹ́ bí àwọn ìjápọ̀ tí a tọ́jú wọn — àwọn fáìlì àwòrán fúnra wọn kò ní kó sínú ìgbàsílẹ̀ náà.",
  "exports.backupTitle": "Àfẹ̀yìntì ní kíkún",
  "exports.backupDesc": "Fáìlì kan pẹ̀lú àwọn ọjà ilé-iṣẹ́ yìí, àwọn ibùdó, ìwọ̀n ọjà, ìwé ìṣíkiri ní kíkún, àwọn olùpèsè, ríra ọjà, àwọn àṣẹ, àwọn ìpadàbọ̀, àwọn ìkà àti àwọn ìtòjọ — pẹ̀lú àwọn ètò profaili rẹ̀. Pa á mọ́ sí ibì kan tí o ṣàkóso.",
  "exports.backupIncludes1": "Àwọn ọjà, àwọn kóòdù, owó iye àti àkọsílẹ̀",
  "exports.backupIncludes2": "Àwọn ibùdó àti iye fún ibùdó kọ̀ọ̀kan",
  "exports.backupIncludes3": "Gbogbo ìṣíkiri, pẹ̀lú ẹni tí ó ṣe é àti àkókò",
