  "valuation.noRetailPrice": "kò sí owó ọjà",
  "valuation.footnote": "Iye owó iye máa ń lo owó ẹ̀yọ lọ́wọ́lọ́wọ́ ọjà kọ̀ọ̀kan, nítorí náà gbígbà ní owó tuntun máa ń tún gbogbo ṣẹ́ẹ̀fù ṣe ìdáiyele. Àwọn ẹ̀yọ tí a pa mọ́ síbẹ̀ ni a kà níbí — wọ́n wà lọ́wọ́, wọ́n kàn ṣe ìlérí fún àṣẹ kan. A kì í wo owó tí ó sọnù gẹ́gẹ́ bí òdo rárá; fi pápá kan sílẹ̀ ní òfo títí a ó fi mọ nọ́mbà náà.",
