  "print.subtitleEssentials": "Àwọn àmì tí a lè ṣàyẹ̀wò, àwọn ìwé ọjà, àwọn àkọsílẹ̀ yíyàn, àwọn ìwé ìdíyelé oníbàárà, àwọn ìwé gbígbà owó àti àwọn ìwé ìpadàbọ̀.",
