  "print.templateIsBusiness": "{label} jẹ́ ẹ̀yà Business",
  "print.supplierBlockedDesc": "Àwọn ìwé olùpèsè máa ń lọ pẹ̀lú ètò Business — àwọn olùpèsè, ríra ọjà àti àwọn àṣẹ ríra. Gbogbo ohun tí o ní nísinsìnyí máa ń ṣiṣẹ́ síbẹ̀.",
  "print.seeBusiness": "Wo ohun tí Business ní",
  "print.nothingToPrint": "Kò sí ohun kan láti tẹ̀wé síbẹ̀",
  "print.pickOrderHint": "Yan àṣẹ ríra kan láti inú àkọsílẹ̀ náà láti ṣe àkọ́kọ́-wò ìwé náà.",
  "print.pickCustomerOrderHint": "Yan àṣẹ oníbàárà kan láti inú àkọsílẹ̀ náà láti ṣe àkọ́kọ́-wò ìwé náà.",
  "print.pickReturnHint": "Yan ìpadàbọ̀ tí a kọ sílẹ̀ kan láti inú àkọsílẹ̀ náà láti ṣe àkọ́kọ́-wò ìwé náà.",
  "print.chooseStyleHint": "Yan ọ̀nà kan, lẹ́yìn náà yan àwọn ọjà láti inú àkọsílẹ̀ náà. Àkọ́kọ́-wò máa ń fi ohun tí ó jáde láti inú ẹ̀rọ ìtẹ̀wé hàn gan-an.",
  "print.howToReach": "Bí o ṣe lè dé ẹ̀rọ ìtẹ̀wé rẹ",
  "print.howIntro": "Àpù yìí máa ń sopọ̀ mọ́ àwọn ẹ̀rọ ìtẹ̀wé tí o ti ní tẹ́lẹ̀ — kì í ṣe ẹ̀rọ ìtẹ̀wé fúnra rẹ̀. Ọ̀nà mẹ́rin ló wà láti dé ọ̀kan, àwọn àmì sì máa ń tẹ̀ sórí ètò méjèèjì nípa èyíkéyìí nínú wọn. Àwọn ìwé ìkó ọjà jọ, àwọn àṣẹ ríra, àwọn ìwé olùpèsè àti àwọn ìròyìn jẹ́ Business nìkan, láìka ìsopọ̀ sí.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "Láti ojúewé yìí, lórí Chrome tàbí Edge orí kọ̀ǹpútà àti lórí Chrome Android: yan ẹ̀rọ ìtẹ̀wé àmì rẹ, àwọn àmì yóò sì lọ tààrà sí i. Kò ṣiṣẹ́ ní Safari iOS — lórí iPhone, ìtẹ̀wé Bluetooth máa ń wá pẹ̀lú àpù alágbèéká dípò rẹ̀. Ẹ̀rọ ìtẹ̀wé tí ó ń sọ Zebra ZPL nìkan tàbí èdè Brother fúnra rẹ̀ kò ní lóye àwọn àmì tí ojúewé yìí ń ránṣẹ́; a máa ń ṣàyẹ̀wò èyí lòdì sí àwọn ẹ̀rọ ìtẹ̀wé tòótọ́ ṣáájú kí a tó pè é ní ṣíṣiṣẹ́.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Fi ẹ̀rọ ìtẹ̀wé náà sori Wi-Fi ṣọ́ọ̀bù rẹ, lẹ́yìn náà lo bọ́tìnì Tẹ̀wé — ó máa ń tẹ̀ nípa ẹ̀rọ ìtẹ̀wé tí a fi sori kọ̀ǹpútà yìí, nípa nẹ́tíwọ́ọ̀kì ṣọ́ọ̀bù náà. Lórí iPhone, AirPrint ti wà nínú rẹ̀: ẹ̀rọ ìtẹ̀wé AirPrint lórí Wi-Fi kan náà máa ń hàn nínú ìwé ìtẹ̀wé, láìsí okùn àti láìsí àpù tí a nílò, àpù náà kò sì nílò kóòdù AirPrint pàtàkì kankan. Ẹ̀rọ ìtẹ̀wé náà gbọ́dọ̀ ṣàtìlẹ́yìn AirPrint (ọ̀pọ̀lọpọ̀ àwọn tuntun máa ń ṣe bẹ́ẹ̀) àti pé fóònù àti ẹ̀rọ ìtẹ̀wé gbọ́dọ̀ wà lórí Wi-Fi kan náà.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "So ẹ̀rọ ìtẹ̀wé náà mọ́ nẹ́tíwọ́ọ̀kì ṣọ́ọ̀bù rẹ pẹ̀lú okùn Ethernet, fi í sori kọ̀ǹpútà náà, kí o sì tẹ̀ nípa bọ́tìnì Tẹ̀wé. Ethernet jẹ́ ọ̀nà kọ̀ǹpútà àti orí tábìlì — àwọn iPhone kò máa ń lo okùn Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "So ẹ̀rọ ìtẹ̀wé náà mọ́ kọ̀ǹpútà náà pẹ̀lú okùn rẹ̀, kí o sì lo bọ́tìnì Tẹ̀wé — ó máa ń tẹ̀ nípa ẹ̀rọ ìtẹ̀wé tí a fi síbẹ̀. Lórí fóònù Android pẹ̀lú okùn USB OTG, bọ́tìnì USB tí ó wà lókè máa ń bá ẹ̀rọ ìtẹ̀wé náà sọ̀rọ̀ tààrà. Àwọn iPhone kò lè tẹ̀ nípa USB tààrà — kò sí WebUSB níbẹ̀ — nítorí náà lo Wi-Fi / AirPrint, tàbí Bluetooth láti inú àpù alágbèéká.",
  "print.howCordsLead": "Àwọn okùn síbẹ̀ máa ń ṣiṣẹ́ fún àwọn iPhone, ní ìgbésẹ̀ kan tí ó jìnnà.",
  "print.howCordsBody": "Ẹ̀rọ ìtẹ̀wé USB tí a so mọ́ kọ̀ǹpútà ṣọ́ọ̀bù náà, tàbí ẹ̀rọ ìtẹ̀wé Ethernet tí a so mọ́ nẹ́tíwọ́ọ̀kì náà, máa ń hàn lórí iPhone rẹ nípa Wi-Fi ṣọ́ọ̀bù náà (AirPrint / ẹ̀rọ ìtẹ̀wé tí a pín) — àwọn okùn máa ń fi ẹ̀rọ ìtẹ̀wé náà sí nẹ́tíwọ́ọ̀kì náà ní ìdúróṣinṣin, fóònù náà sì máa ń dé ọ̀dọ̀ rẹ̀ láìsí okùn.",
  "print.howOfflineLead": "Bí ìhtéẹ̀nẹ́ẹ̀tì bá já,",
  "print.howOfflineBody": "àwọn àmì àti àwọn ìwé tí ó ti wà lórí ojúewé yìí síbẹ̀ máa ń tẹ̀ — bọ́tìnì Tẹ̀wé, PDF Àwọn Àmì, Bluetooth àti USB kò nílò ìsopọ̀ kankan. Ohun tí ó nílò ìhtéẹ̀nẹ́ẹ̀tì ni gbígbé ojúewé náà àti àwọn ọjà rẹ̀ ní àkọ́kọ́. Ọ̀nà aláìsí-ìsopọ̀ ní kíkún (ṣiṣẹ́ nínú àpù náà láìsí ìsopọ̀ rárá) jẹ́ ìkọ́lé ọ̀tọ̀, tí ó tóbi jù, a kò sì sọ pé ó wà níbí.",
