  "settings.cancelSubscription": "Fagilé Ìforúkọsílẹ̀",
  "settings.cancelTerms.appleLink": "Àwọn ìtọ́nisọ́nà ìfagilé Apple",
  "settings.cancelTerms.googlePlayLink": "Àwọn ìtọ́nisọ́nà ìfagilé Google Play",
  "settings.cancelTerms.graceTitle": "Lẹ́yìn tí àkókò tí o sanwó fún parí — ọjọ́ ìdádúró 15, lẹ́yìn náà píparẹ́:",
  "settings.cancelTerms.intro": "Àwọn wọ̀nyí ni àwọn òfin fún àwọn ìforúkọsílẹ̀ Luminous StockHaven tí a sanwó fún. Ìsanwó ìforúkọsílẹ̀ wẹ́ẹ̀bùsáìtì ń lọ nípasẹ̀ Stripe. O le fagilé ìforúkọsílẹ̀ rẹ fúnra rẹ nígbàkigbà nípa lílo bọ́tìnì Fagilé Ìforúkọsílẹ̀ ní ìsàlẹ̀ — kò nílò ìfọwọ́sí òṣìṣẹ́. A tún le mú àwọn ìbéèrè ìfagilé àti ìdápadà owó ṣe nípasẹ̀ olùbáṣepọ̀ ìtìlẹ́yìn oníbàárà osise, theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "O le fagilé ìforúkọsílẹ̀ rẹ fúnra rẹ nígbàkigbà. Kò nílò ìfọwọ́sí òṣìṣẹ́. Àwọn ìtúnṣe ọjọ́ iwájú máa ń dúró nìkan lẹ́yìn tí olùpèsè ìsanwó bá jẹ́rìí ìfagilé.",
  "settings.cancelTerms.noApprovalTitle": "Fagilé láìsí ìfọwọ́sí:",
  "settings.cancelTerms.paymentBody": "Fún àwọn ìdánwò tí a sanwó fún, ìdánwò ọjọ́ méje nílò ọ̀nà ìsanwó ní ìforúkọsílẹ̀. Àyàfi tí a bá fagilé nínú àkókò ìfagilé ìdánwò tí ó yẹ, ètò oṣooṣù tí a yàn yóò gba owó lọ́wọ́ rẹ fúnra rẹ̀ lẹ́yìn ìdánwò náà. Iye owó, ọjọ́ ìsanwó àkọ́kọ́, àti àkókò ìfagilé tí ó kan olùpèsè gbọdọ̀ hàn ní ìforúkọsílẹ̀. Ìsanwó ìdánwò ń lọ nípasẹ̀ Stripe.",
  "settings.cancelTerms.paymentTitle": "Ọ̀nà ìsanwó àti ìtúnṣe aládàáṣiṣẹ́:",
  "settings.cancelTerms.remainingBody": "Bí o bá ti sanwó fún àkókò ìsanwó kan, o le pa ìwọlé mọ́ títí di ọjọ́ tí a jẹ́rìí pé o sanwó dé. Ìparí ṣáájú nílò ìjẹ́rìí olùpèsè tí ó yẹ àti ìmú owó ìdápadà tí ó yẹ. Ìwọlé ìdánwò ọ̀fẹ́ parí gẹ́gẹ́ bí ọjọ́ ìparí ìdánwò tí olùpèsè jẹ́rìí.",
  "settings.cancelTerms.remainingTitle": "Ìwọlé tí ó kù:",
  "settings.cancelTerms.storesBody": "Bí o bá forúkọsílẹ̀ nípasẹ̀ Google Play tàbí Apple App Store rí, ìforúkọsílẹ̀ rẹ ni ilé ìtajà náà ń sanwó fún tí ó sì ń ṣàkóso. O lè nílò láti fagilé e tààrà nínú apá ìforúkọsílẹ̀ ti àkáǹtì Google tàbí Apple kan náà tí o lò láti forúkọsílẹ̀. Ìfagilé ìforúkọsílẹ̀ wẹ́ẹ̀bùsáìtì ọ̀tọ̀, yíyọ áppù yìí kúrò, tàbí bíbéèrè píparẹ́ àkáǹtì Luminous StockHaven kò fagilé ìforúkọsílẹ̀ tí ilé ìtajà ń sanwó fún fúnra rẹ̀. Ṣàyẹ̀wò ìwé ìsanwó ríra rẹ láti jẹ́rìí ẹni tí ó ń gba owó lọ́wọ́ rẹ.",
  "settings.cancelTerms.storesTitle": "Àwọn ìforúkọsílẹ̀ Google Play àti Apple App Store (bí o bá forúkọsílẹ̀ nípasẹ̀ ilé ìtajà rí):",
  "settings.cancelTerms.title": "Àwọn Òfin àti Ìpinnu Ìfagilé",
  "settings.cancelTerms.trialBody": "A le lo ìdánwò ọjọ́ méje lẹ́ẹ̀kan ṣoṣo fún oníbàárà tí ó yẹ kọ̀ọ̀kan. Ìfagilé ìdánwò tàbí ìforúkọsílẹ̀ kò fún ni ní ìdánwò mìíràn; àwọn oníbàárà tí ó padà gbọdọ̀ yan ìforúkọsílẹ̀ tí a sanwó fún.",
  "settings.cancelTerms.trialTitle": "Ìdánwò ọ̀fẹ́ kan:",
  "settings.canceled.endsOn": "A ti fagilé ìforúkọsílẹ̀ yìí, yóò sì parí ní {date}. O pa ìwọlé kíkún mọ́ títí di ìgbà náà.",
  "settings.delete.checking": "Ń ṣàyẹ̀wò ìbéèrè píparẹ́ tí ó wà tẹ́lẹ̀…",
  "settings.delete.description": "Béèrè yíyọ àkáǹtì ìwọlé Luminous StockHaven rẹ kúrò.",
  "settings.delete.dialogDescription": "Èyí béèrè àyẹ̀wò píparẹ́ àkáǹtì. Kò yọ ìwọlé rẹ tàbí ọjà ọjà kúrò lẹ́sẹ̀kẹsẹ̀, kò sì fagilé ìforúkọsílẹ̀ Stripe kankan. Tẹ \"{word}\" láti jẹ́rìí pé o fẹ́ fi ìbéèrè náà ránṣẹ́.",
  "settings.delete.dialogTitle": "Béèrè Píparẹ́ Àkáǹtì",
  "settings.delete.enterDelete": "Tẹ {word} láti jẹ́rìí",
  "settings.delete.exportFirst": "Kó ọjà ọjà rẹ jáde ní àkọ́kọ́ bí o bá nílò láti pa àwọn àkọsílẹ̀ rẹ mọ́.",
  "settings.delete.intro": "Fífi ìbéèrè ránṣẹ́ kò pa àkáǹtì rẹ, àwọn ìṣòwò rẹ, tàbí ọjà ọjà rẹ rẹ́ lẹ́sẹ̀kẹsẹ̀. A ń ṣe àyẹ̀wò àwọn ìbéèrè lọ́tọ̀ ṣáájú kí píparẹ́ tó le parí. Ìbéèrè yìí kò fagilé ìforúkọsílẹ̀ Stripe tàbí dá ìsanwó ọjọ́ iwájú dúró; ìfagilé ìforúkọsílẹ̀ gbọdọ̀ ṣe lọ́tọ̀ nípasẹ̀ olùpèsè ìsanwó.",
  "settings.delete.keepAccount": "Pa Àkáǹtì Mọ́",
