  "settings.pastDue.body": "Ìsanwó rẹ tí ó kẹ́yìn kò lọ. Ṣe àtúnṣe ọ̀nà ìsanwó rẹ láti ojú ìwé Àgbéga — Stripe yóò gbìyànjú lẹ́ẹ̀kan sí i ní ìtòlẹ́sẹẹsẹ rẹ̀, a kò sì ní fagilé ìforúkọsílẹ̀ rẹ ṣáájú. Bí o kò bá dá ọ lójú ohun tí o ó ṣe, kàn sí ìtìlẹ́yìn ní theluminousbookshop@outlook.com.",
