  "settings.switcher.newDescription": "Ìṣòwò kọ̀ọ̀kan ń pa àwọn ọjà rẹ̀, àwọn ibi rẹ̀, àwọn olùpèsè rẹ̀ àti àwọn àṣẹ ríra rẹ̀ mọ́. Kò sí ohun tí a pín láàrin wọn.",
