  "settings.title": "Àwọn ètò",
  "settings.trial.cancelKeeps": "Ìfagilé nígbà ìdánwò rẹ ń pa ọjọ́ méje rẹ kíkún mọ́ — ìwọlé parí ní {date}, a kò sì ní gba owó lọ́wọ́ rẹ.",
  "staff.access.noSeatBody": "Àkáǹtì rẹ kò ní ìjókòó òṣìṣẹ́ fún ìṣòwò yìí, nítorí náà ọjà ọjà rẹ̀ wà ní títì. Béèrè lọ́wọ́ oníni láti fi ọ́ kún un ní Òṣìṣẹ́ àti àwọn ipa.",
  "staff.access.noSeatTitle": "Ìṣòwò yìí kò ṣí sí ìwọlé rẹ",
  "staff.access.pendingBody": "Ìṣòwò yìí ní ìpè fún ímeèlì rẹ tí a kò tíì mú ṣiṣẹ́. Béèrè lọ́wọ́ oníni láti ṣètò ipò òṣìṣẹ́ rẹ sí ṣiṣẹ́. Kò sí ohun tí ó hàn níbí títí di ìgbà náà.",
  "staff.access.pendingTitle": "Ìpè rẹ kò tíì ṣiṣẹ́",
  "staff.access.signOut": "Jáde",
  "staff.access.suspendedBody": "Alákóso kan ti dá àkáǹtì òṣìṣẹ́ yìí dúró fún ìṣòwò tí ó ń ṣiṣẹ́. Béèrè lọ́wọ́ wọn láti dá ọ padà sí ṣiṣẹ́, lẹ́yìn náà wọlé lẹ́ẹ̀kan sí i.",
  "staff.access.suspendedTitle": "A dá ìwọlé rẹ dúró fún ìgbà díẹ̀",
  "staff.addFirst": "Fi òṣìṣẹ́ àkọ́kọ́ kún un",
  "staff.addMember": "Fi òṣìṣẹ́ kún un",
  "staff.emptyBody": "Fi ènìyàn kan kún un, fún wọn ní ipa àti àwọn ìyọ̀ǹda tí ó bá a lọ, a ó sì pè wọ́n nípasẹ̀ ímeèlì láti wọlé sí ìṣòwò yìí.",
  "staff.emptyTitle": "Kò sí òṣìṣẹ́ sí i",
  "staff.eyebrow": "Ẹgbẹ́",
  "staff.how.p1": "Ọmọ ẹgbẹ́ kọ̀ọ̀kan ní ipa àti àkójọ ìyọ̀ǹda tirẹ̀, nítorí náà o le bẹ̀rẹ̀ láti ipa kan kí o sì yí ohun kan padà láìṣe ipa tuntun. Ṣíṣe àtúnṣe ipa kò tún àwọn ọmọ ẹgbẹ́ tí ó wà lórí rẹ̀ tẹ́lẹ̀ kọ — ṣí ọmọ ẹgbẹ́ kan láti tún lo àwọn àṣàyàn ipa wọn.",
  "staff.how.p2": "Àwọn ipa àṣà jẹ́ ẹ̀yà Business: Essentials ń lo àwọn ipa márùn-ún tí a ṣe sínú rẹ̀ (Oníni, Alákóso, Akọ̀wé ọjà, Akọ̀wé títà, Olùwòran).",
  "staff.how.p3": "A ń fi àwọn ìpè ránṣẹ́ nípasẹ̀ ímeèlì. Ọmọ ẹgbẹ́ kan le wọlé nìkan lẹ́yìn tí ó bá gbà, yíyọ ẹnìkan kúrò nínú àkójọ yìí kò pa àkáǹtì áppù wọn rẹ́.",
  "staff.how.p4": "Ilé ìtajà ni ibi tí a yàn ènìyàn sí. A kọ ọ́ sílẹ̀ lórí káàdì wọn; ohun tí wọ́n le ṣí ṣì jẹ́ ìpinnu ipa àti àwọn ìyọ̀ǹda wọn.",
  "staff.how.p5": "Àwọn ìyọ̀ǹda ń pinnu ohun tí ẹnìkọ̀ọ̀kan le ṣí: àwọn ohun èlò àkójọ tí ó wà lóde ipa wọn ni a fi pamọ́, àdírẹ́sì tí a dí sì ń fi ìkìlọ̀ “kò sí lórí ipa rẹ” hàn dípò ojú ìwé náà. Àyípadà ń ṣiṣẹ́ nígbà tí ẹni náà bá gbé áppù náà jáde lẹ́ẹ̀kan sí i; dídá ọmọ ẹgbẹ́ dúró ń ti wọ́n jáde pátápátá.",
  "staff.how.p6": "Àwọn alákóso le rí gbogbo dátà kí wọ́n sì yí i padà, ṣàkóso àwọn olùlò áppù àti àwọn ipa, a kò sì ní dí wọ́n lọ́wọ́ nípasẹ̀ ipa òṣìṣẹ́ rárá. Ẹnìkan tí kò ní àkọsílẹ̀ òṣìṣẹ́ — oníni ìṣòwò tuntun — ń pa ìwọlé kíkún mọ́.",
  "staff.howTitle": "Bí òṣìṣẹ́ àti àwọn ipa ṣe ń ṣiṣẹ́",
